<script setup>
import ServiceTargetSummary from './ServiceTargetSummary.vue'
import ProtectedAttachment from './ProtectedAttachment.vue'
import { complaintDisplayType, serviceTopics, complaintStatuses, verificationOutcomes, reservationStatuses } from '../composables/complaintForm.js'
defineProps({ record: {type:Object,required:true}, targetProgress:{type:Object,default:null} })
</script>
<template><section class="complaint-record"><h3>#{{ record.id }} · {{ complaintDisplayType(record) }} · {{ complaintStatuses[record.status] || record.status }}</h3><p>提交时间：{{ record.submitted_at }}（校园时间）</p><p v-if="record.handler">首受理人：{{ record.handler.display_name }} · {{ record.accepted_at }}；受理表示开始核查，不代表已解决。</p><p v-if="record.initial_arrangement">公开初步安排：{{ record.initial_arrangement }}；这不是维修完成承诺。</p><p v-if="record.server_now">服务端读取时刻：{{ record.server_now }}（{{ record.campus_zone }}）</p><p v-if="record.status==='closed'">结案方式：{{ record.closure_type==='auto_closed'?'确认期届满，系统自动结案':record.closure_type==='confirmed'?'本人确认反馈后结案':record.closure_type || '未提供' }}；结案登记：{{ record.closed_at || '未提供' }}</p><ServiceTargetSummary :record="record" :progress="targetProgress" /><p class="description">{{ record.description }}</p><section v-if="record.service_kind==='facility_repair'" class="context"><h4>设施报修内容与分级</h4><p>故障类型：{{ record.fault_type }}；影响范围：{{ record.impact_scope }}</p><p>提交时安全风险：{{ record.safety_risk?'有':'未报告' }}；区域无法安全使用：{{ record.unsafe_area?'是':'否' }}。</p><p>初始优先级：{{ record.initial_priority==null?'未配置，待管理员核定':record.initial_priority+'级' }}<span v-if="record.priority_status==='safety_override'">（安全规则覆盖）</span><span v-else-if="record.priority_status==='mapped'">（映射版本{{ record.priority_mapping_version }}）</span>。等级仅用于排序，不承诺修复时限。</p><p v-if="record.triaged_priority">管理员核定：{{ record.triaged_priority }}级；核定风险：{{ record.triaged_safety_risk?'存在安全风险':'无安全风险' }}；区域不可安全使用：{{ record.triaged_unsafe_area?'是':'否' }}；时间{{ record.triaged_at }}。</p></section><p v-else-if="record.service_kind==='other_service'">其他服务类别：{{ serviceTopics[record.service_topic] || record.service_topic }}。此类问题由管理员直接处置，不进入报修优先级队列。</p><div v-if="record.context_snapshot" class="context"><h4>提交时关联快照</h4><p>{{ record.context_snapshot.room_name }} · {{ record.context_snapshot.building || '楼栋未登记' }} · {{ record.context_snapshot.floor || '楼层未登记' }} · {{ record.context_snapshot.location || '位置未登记' }}</p><p v-if="record.context_snapshot.reservation_id">预约#{{ record.context_snapshot.reservation_id }} · 座位{{ record.context_snapshot.seat_no }} · {{ record.context_snapshot.date }} {{ record.context_snapshot.start_time }}—{{ record.context_snapshot.end_time }} · 提交时状态：{{ reservationStatuses[record.context_snapshot.status_at_submission] || record.context_snapshot.status_at_submission }}</p></div><p v-else-if="record.type==='occupation'">本次关联的空间/预约快照未提供。</p><p v-else>本次服务已关联所选空间。</p><p>提交本身不代表已受理或解决，不延长签到期限、不恢复已结束或已取消预约；现场情况以实际核实处理为准。</p><section v-if="record.current_feedback" class="feedback-record"><h4>当前最新正式反馈 #{{ record.current_feedback.id }}</h4><p class="description">结果：{{ record.current_feedback.result }}</p><p class="description">公开依据：{{ record.current_feedback.basis }}</p><p>发出：{{ record.current_feedback.feedback_at }}；记录人：{{ record.current_feedback.actor_display_name }}</p><p>{{ record.status==='awaiting_confirmation'?'本次反馈确认截止':'本次反馈确认截止（历史）' }}：{{ record.current_feedback.deadline }}。每次正式反馈重新起算7×24小时，以服务端当前许可动作为准。</p><p v-if="record.current_feedback.response_type">反馈响应：{{ ({confirmed:'本人已确认',objected:'已提出异议，回到处理中',auto_closed:'到期无响应，系统结案'})[record.current_feedback.response_type] || record.current_feedback.response_type }}；登记{{ record.current_feedback.responded_at }}</p></section><h4>照片材料（{{ record.attachment_count }}张）</h4><p v-if="!record.attachments.length">本次未附照片。</p><div class="attachments"><ProtectedAttachment v-for="attachment in record.attachments" :key="attachment.id" :attachment="attachment" /></div><h4>已记录进度</h4><ul><li v-for="event in record.events" :key="event.id">事件#{{ event.id }} · {{ ({submitted:'本人提交，待受理',accepted:'已受理并说明初步安排',verification:'追加核实记录',feedback:'正式反馈已发出',service_progress:event.service_progress_stage==='handoff'?'维修渠道已交接':'维修进度更新',withdrawn:'本人撤回',confirmed:'本人确认反馈并结案',objected:'本人补充异议，回到处理中',auto_closed:'确认期届满，系统自动结案'})[event.type] || event.type }} · 登记{{ event.created_at }}<span v-if="event.occurred_at"> · 发生{{ event.occurred_at }}</span><p v-if="event.outcome">{{ verificationOutcomes[event.outcome] || event.outcome }}</p><p v-if="event.public_note">公开进度：{{ event.public_note }}</p><p v-if="event.service_progress_stage">维修渠道：{{ event.maintenance_channel }}；交接时间：{{ event.handoff_at }}</p><p v-if="event.triage_priority">核定优先级：{{ event.triage_priority }}级；公开理由：{{ event.triage_reason }}</p><p v-if="event.related_feedback_id">关联正式反馈#{{ event.related_feedback_id }}</p><p v-if="event.result" class="description">正式反馈结果：{{ event.result }}</p><p v-if="event.basis" class="description">公开反馈依据：{{ event.basis }}</p><p v-if="event.feedback_deadline">本次确认截止：{{ event.feedback_deadline }}</p><p v-if="event.description" class="description">异议说明：{{ event.description }}</p><p v-if="event.source==='system'">系统自动记录</p><p v-if="event.actor_display_name">记录人：{{ event.actor_display_name }}</p></li></ul></section></template>
<style scoped>.complaint-record{display:grid;gap:12px;min-width:0;overflow-wrap:anywhere}.description{white-space:pre-wrap}.attachments{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(240px,100%),1fr));gap:12px}.feedback-record{padding:12px;border:1px solid var(--border);border-radius:var(--r-md);display:grid;gap:8px}.context{background:var(--surface-2);border-radius:var(--r-md);padding:12px}</style>
